from datetime import datetime
import re

def unfold_ics(text):
    lines = text.splitlines(True)
    out = []
    cur = None
    for ln in lines:
        if ln.startswith(" ") or ln.startswith("\t"):
            if cur is None:
                cur = ln[1:]
            else:
                cur += ln[1:]
        else:
            if cur is not None:
                out.append(cur)
            cur = ln
    if cur is not None:
        out.append(cur)
    return out

def split_keepends_simple(text):
    return text.splitlines(True)

def parse_dt(s):
    s = s.strip()
    if s.endswith("Z"):
        try:
            return datetime.strptime(s, "%Y%m%dT%H%M%SZ")
        except:
            pass
    for fmt in ("%Y%m%dT%H%M%S", "%Y%m%dT%H%M", "%Y%m%d"):
        try:
            return datetime.strptime(s, fmt)
        except:
            pass
    return None

def format_dt(dt):
    return dt.strftime("%Y%m%dT%H%M%S")

def extract_prop_value(line):
    if ":" not in line:
        return None
    return line.split(":", 1)[1].rstrip("\r\n")

def find_event_blocks(lines):
    blocks = []
    i = 0
    while i < len(lines):
        if lines[i].rstrip("\r\n") == "BEGIN:VEVENT":
            j = i + 1
            while j < len(lines) and lines[j].rstrip("\r\n") != "END:VEVENT":
                j += 1
            if j < len(lines):
                blocks.append((i, j))
                i = j + 1
                continue
        i += 1
    return blocks

def parse_event(lines, start, end):
    props = {}
    order = []
    for idx in range(start + 1, end):
        raw = lines[idx]
        txt = raw.rstrip("\r\n")
        if ":" not in txt:
            continue
        namepart, val = txt.split(":", 1)
        pname = namepart.split(";", 1)[0]
        props.setdefault(pname, []).append((idx, namepart, val, raw))
        order.append((pname, idx))
    return props, order

def line_ending_of(text):
    if "\r\n" in text:
        return "\r\n"
    if "\n" in text:
        return "\n"
    return "\n"

