import re
from datetime import datetime
from dateutil import parser as dtparser

def norm_path(p):
    if p is None:
        return None
    if p.startswith('/testbed/'):
        p = p[len('/testbed/')-1:] if False else p[len('/testbed/'):]
    if p.startswith('./'):
        p = p[2:]
    return p

def get_record(data, args):
    if 'username' in args:
        path = 'emails/' + args['username']
    else:
        path = args.get('file', args.get('result_file'))
    if path is None:
        return None, None
    n = norm_path(path)
    fs = data.get('final_state', {})
    if n in fs:
        return n, fs[n]
    alt1 = './' + n
    alt2 = '/testbed/' + n
    for k in fs:
        nk = norm_path(k)
        if nk == n:
            return k, fs[k]
    return n, None

def parse_events(text):
    if text is None:
        return None
    if text == '[unknown predicted content]':
        return None
    if text == '[file does not exist]':
        return []
    t = text.strip()
    if not t:
        return None
    if t.startswith('INITIAL content'):
        return None
    if 'No events found for ' in t:
        return []
    parts = t.split('-' * 50)
    events = []
    for part in parts:
        p = part.strip()
        if not p:
            continue
        fields = {}
        for line in p.splitlines():
            if ':' not in line:
                continue
            k, v = line.split(':', 1)
            fields[k.strip().lower()] = v.strip()
        if fields:
            events.append(fields)
    return events

def to_dt(s):
    try:
        return dtparser.parse(s)
    except Exception:
        return None

def overlap(a_start, a_end, b_start, b_end):
    return a_start < b_end and b_start < a_end

def evaluate_calendar_no_overlap(data, args):
    _, content = get_record(data, args)
    if content is None:
        return 'UNKNOWN'
    events = parse_events(content)
    if events is None:
        return 'UNKNOWN'
    intervals = []
    for ev in events:
        st = ev.get('start time')
        en = ev.get('end time')
        if st is None or en is None:
            return 'UNKNOWN'
        ds = to_dt(st)
        de = to_dt(en)
        if ds is None or de is None:
            return 'UNKNOWN'
        intervals.append((ds, de))
    for i in range(len(intervals)):
        for j in range(i + 1, len(intervals)):
            if overlap(intervals[i][0], intervals[i][1], intervals[j][0], intervals[j][1]):
                return 'UNMET'
    return 'MET'

