def prop_value(unfolded_event_lines, key):
    prefix = key + ":"
    prefix2 = key + ";"
    for ln in unfolded_event_lines:
        raw = ln.rstrip("\r\n")
        if raw.startswith(prefix):
            return raw[len(prefix):]
        if raw.startswith(prefix2):
            return raw.split(":", 1)[1] if ":" in raw else ""
    return None

def remove_event_by_summary(content, summary):
    lines = fold_lines(content)
    unfolded = unfold_ics(content)
    # map unfolded event boundaries back approximately using folded lines indices by scanning folded lines
    folded = lines
    events = []
    i = 0
    while i < len(folded):
        if folded[i].rstrip("\r\n") == "BEGIN:VEVENT":
            start = i
            j = i + 1
            while j < len(folded) and folded[j].rstrip("\r\n") != "END:VEVENT":
                j += 1
            if j < len(folded):
                events.append((start, j))
                i = j
        i += 1

    remove_ranges = []
    for start, end in events:
        ev_lines = folded[start:end+1]
        unfolded_ev = []
        for ln in ev_lines:
            if (ln.startswith(" ") or ln.startswith("\t")) and unfolded_ev:
                unfolded_ev[-1] = unfolded_ev[-1].rstrip("\r\n") + ln[1:]
            else:
                unfolded_ev.append(ln)
        if prop_value(unfolded_ev, "SUMMARY") == summary:
            remove_ranges.append((start, end))

    if not remove_ranges:
        return content

    keep = []
    idx = 0
    rr = iter(remove_ranges)
    current = next(rr, None)
    while idx < len(folded):
        if current and current[0] <= idx <= current[1]:
            idx = current[1] + 1
            current = next(rr, None)
        else:
            keep.append(folded[idx])
            idx += 1
    return "".join(keep)

def append_event(content, action):
    newline = "\r\n" if "\r\n" in content else "\n"
    if content == "":
        header = [
            "BEGIN:VCALENDAR" + newline,
            "VERSION:2.0" + newline,
            "PRODID:-//OfficeBench//Calendar//EN" + newline,
            "END:VCALENDAR" + newline,
        ]
        content = "".join(header)

    lines = fold_lines(content)
    end_idx = None
    for i, ln in enumerate(lines):
        if ln.rstrip("\r\n") == "END:VCALENDAR":
            end_idx = i
            break
    if end_idx is None:
        return content

    summary = get_arg(action, "summary", "event_title", "title")
    start = get_arg(action, "start_time", "start")
    end = get_arg(action, "end_time", "end")
    description = get_arg(action, "description")
    location = get_arg(action, "location")

    ev = []
    ev.append("BEGIN:VEVENT" + newline)
    if summary is not None:
        ev.append(f"SUMMARY:{summary}" + newline)
    if start is not None:
        ev.append(f"DTSTART:{start}" + newline)
    if end is not None:
        ev.append(f"DTEND:{end}" + newline)
    if description is not None:
        ev.append(f"DESCRIPTION:{description}" + newline)
    if location is not None:
        ev.append(f"LOCATION:{location}" + newline)
    ev.append("END:VEVENT" + newline)

    new_lines = lines[:end_idx] + ev + lines[end_idx:]
    return "".join(new_lines)

