def parse_cells(text):
    cells = {}
    if text is None:
        return cells
    for r, c, v in re.findall(r'\((\d+),\s*(\d+)\):\s*([^\t\n\r]*)', text):
        cells[(int(r), int(c))] = v
    return cells

def to_num(s):
    s = s.strip()
    try:
        return float(s)
    except:
        return None

