def parse_cells(text):
    cells = {}
    if text is None:
        return cells
    for r, c, v in re.findall(r'\((\d+),\s*(\d+)\):\s*([^\t\r\n]+)', text):
        cells[(int(r), int(c))] = v.strip()
    return cells

def coerce_num(s):
    s = s.strip()
    try:
        if re.fullmatch(r'-?\d+', s):
            return int(s)
        if re.fullmatch(r'-?(?:\d+\.\d*|\.\d+)', s):
            return float(s)
    except:
        pass
    return None

def compare(a, op, b):
    na, nb = coerce_num(a), coerce_num(b)
    if na is not None and nb is not None:
        a, b = na, nb
    if op == '==':
        return a == b
    elif op == '!=':
        return a != b
    elif op == '>':
        return a > b
    elif op == '>=':
        return a >= b
    elif op == '<':
        return a < b
    elif op == '<=':
        return a <= b
    return None

