                return None
            actual = cells.get((int(row), int(col)))
            if actual is None:
                return False
            if compare(actual, str(op), str(expected)) is not True:
                return False
        else:
            m = re.match(r'\((\d+),\s*(\d+)\)\s*(==|!=|>=|<=|>|<)\s*(.+)', str(chk).strip())
