    out = []
    for m in matches or []:
        mm = re.match(r'^\s*\(\s*(\d+)\s*,\s*(\d+)\s*\)\s*:\s*(.*)\s*$', str(m), re.S)
        if not mm:
            return None
        out.append((int(mm.group(1)), int(mm.group(2)), mm.group(3)))
    return out

