        bb = str(b)
        if op == '==':
            return aa == bb
        if op == '!=':
            return aa != bb
        return None
    if op == '>':
        return an > bn
    if op == '>=':
        return an >= bn
    if op == '<':
        return an < bn
    if op == '<=':
        return an <= bn
    if op == '==':
        return an == bn
    if op == '!=':
        return an != bn
    return None

