def parse_cells(text):
    cells = {}
    if text is None:
        return cells
    for r, c, v in re.findall(r'\((\d+),\s*(\d+)\):\s*([^\t\n\r]*)', text):
        cells[(int(r), int(c))] = v
    return cells

def coerce_num(s):
    s = s.strip()
    try:
        return float(s)
    except:
        return None

def compare(a, op, b):
    na = coerce_num(a)
    nb = coerce_num(b)
    if na is None or nb is None:
        return None
    if op == '==':
        return na == nb
    elif op == '!=':
        return na != nb
    elif op == '>':
        return na > nb
    elif op == '<':
        return na < nb
    elif op == '>=':
        return na >= nb
    elif op == '<=':
        return na <= nb
    return None

