            return None
        key = (int(m.group(1)), int(m.group(2)))
        op = m.group(3)
        rhs = m.group(4).strip()
        if key not in cells:
            return False
        ok = compare(cells[key], op, rhs)
        if ok is None:
            return None
        if not ok:
