def apply_delta(text):
    if text is None:
        return None
    marker = 'INITIAL content '
    wmarker = ' WRITE actions '
    if text.startswith(marker) and wmarker in text:
        rest = text[len(marker):]
        i = rest.find(wmarker)
        initial = rest[:i]
        actions = rest[i + len(wmarker):]
        if initial == '[file does not exist]':
            cur = None
        else:
            cur = initial
        for m in re.finditer(r'(?s)<write[^>]*>(.*?)</write>', actions):
            chunk = m.group(1)
            if cur is None:
                cur = ''
            cur += chunk
        return cur
    return text

def evaluate_diff_contain_text(data, args):
    path = args.get('file') or args.get('result_file')
    content = get_content(data, path)
    if content is None:
        return None
    content = apply_delta(content)
    if content is None:
        return False
    gold = data.get('gold_files', {})
    gpath = norm_path(path)
    gold_content = gold.get(gpath)
    if gold_content is None:
        gold_content = gold.get('/testbed/' + gpath, gold.get('./' + gpath))
    if gold_content is None:
        return None
    return content == gold_content

