def apply_delta(text):
    if not isinstance(text, str):
        return text
    if 'INITIAL content' not in text or 'WRITE actions' not in text:
        return text
    m = re.match(r'INITIAL content(.*)WRITE actions(.*)', text, re.S)
    if not m:
        return text
    initial = m.group(1).strip()
    actions = m.group(2)
    if initial == '[file does not exist]':
        cur = ''
    else:
        cur = initial
    for wm in re.finditer(r'---WRITE---\s*(.*?)\s*---END WRITE---', actions, re.S):
        block = wm.group(1)
        am = re.search(r'append=(True|False)\s*\n(.*)', block, re.S)
        if am:
            append = am.group(1) == 'True'
            content = am.group(2)
            cur = cur + content if append else content
    return cur

