    if rec == '[unknown predicted content]':
        return None
    return True

def apply_delta(rec):
    if rec is None:
        return None
    if not isinstance(rec, str):
        return rec
    if not rec.startswith('INITIAL content'):
        return rec
    m = re.match(r'^INITIAL content (.*?)(?:\nWRITE actions \(\d+\):\n(.*))?$', rec, re.S)
    if not m:
        return rec
    initial = m.group(1)
    writes = m.group(2)
    if initial == '[file does not exist]':
        content = None
    elif initial == '[unknown predicted content]':
        return None
    else:
        content = initial
    if writes:
        parts = re.findall(r'(?:^|\n)- write(?:_to_file)?: ?(.*?)(?=\n- write(?:_to_file)?: |\Z)', writes, re.S)
        if not parts:
            parts = [w.strip() for w in writes.splitlines() if w.strip()]
        for w in parts:
            if content is None:
