        return fs['./' + p]
    if '/testbed/' + p in fs:
        return fs['/testbed/' + p]
    return None

def exists_status(content):
    if content is None:
        return 'unknown'
    if content == '[file does not exist]':
        return 'absent'
    if content == '[unknown predicted content]':
        return 'unknown'
    return 'present'

def compute_current_text(raw):
    if raw is None:
        return None
    if not isinstance(raw, str):
        return raw
    if raw.startswith('INITIAL content'):
        m = re.search(r'WRITE actions.*?:\s*(.*)\Z', raw, re.S)
        if m:
            return m.group(1).strip()
    return raw

