def apply_delta(content):
    if content is None:
        return None
    if not isinstance(content, str):
        return content
    if 'INITIAL content' not in content or 'WRITE actions' not in content:
        return content
    m = re.search(r'INITIAL content:\s*(.*?)(?:\n+WRITE actions:\s*|\Z)', content, re.S)
    initial = m.group(1) if m else ''
    if initial.strip() == '[file does not exist]':
        cur = None
    elif initial.strip() == '[unknown predicted content]':
        return None
    else:
        cur = initial
    m2 = re.search(r'WRITE actions:\s*(.*)\Z', content, re.S)
