    return None

def apply_delta(text):
    if not isinstance(text, str):
        return text
    if not text.startswith('INITIAL content'):
        return text
    m = re.match(r'^INITIAL content \((.*?)\):\n', text, re.S)
    if not m:
        return text
    initial_marker = m.group(1)
    pos = m.end()
    wa = '\nWRITE actions:\n'
    idx = text.find(wa, pos)
    if idx == -1:
        initial = text[pos:]
        writes = ''
    else:
        initial = text[pos:idx]
        writes = text[idx + len(wa):]
    if initial_marker == 'file does not exist':
        content = None
    elif initial_marker == 'unknown predicted content':
        return text
    else:
        content = initial
    for line in writes.splitlines():
        line = line.strip()
        if not line or not line.startswith('- '):
            continue
        s = line[2:]
        if s.startswith('append '):
            m = re.match(r'append at end: (.*)', s, re.S)
            if m:
                if content is None:
                    content = ''
                content += m.group(1)
        elif s.startswith('overwrite'):
            m = re.match(r'overwrite(?: from \d+ to \d+)?: (.*)', s, re.S)
            if m:
                content = m.group(1)
    if content is None:
        return '[file does not exist]'
    return content

def content_for_check(data, args):
    path = args.get('file') or args.get('result_file')
    return apply_delta(get_record(data, path))

