        return text
    marker = 'INITIAL content'
    wmarker = 'WRITE actions'
    if marker in text and wmarker in text:
        i = text.find(marker)
        w = text.find(wmarker, i + len(marker))
        if w != -1:
            initial = text[i + len(marker):w]
            actions = text[w + len(wmarker):]
            content = initial
            for m in re.finditer(r'(?im)^\s*(APPEND|OVERWRITE):\s*', actions):
                pass
            parts = re.split(r'(?im)^\s*(APPEND|OVERWRITE):\s*', actions)
            if len(parts) >= 3:
                j = 1
                while j + 1 < len(parts):
                    kind = parts[j].strip().upper()
                    payload = parts[j + 1]
                    if kind == 'OVERWRITE':
                        content = payload
                    elif kind == 'APPEND':
                        content += payload
                    j += 2
            return content.strip('\n')
    return text

