def diff_apply(delta):
    if not isinstance(delta, str):
        return delta
    if not delta.startswith('INITIAL content'):
        return delta
    m = re.match(r'^INITIAL content(?: \((?:file )?missing\))?:\n', delta)
    if not m:
        m = re.match(r'^INITIAL content:\n', delta)
    if not m:
        return delta
    rest = delta[m.end():]
    marker = '\nWRITE actions:\n'
    idx = rest.find(marker)
    if idx == -1:
        return delta
    initial = rest[:idx]
    writes = rest[idx+len(marker):]
    if initial.strip() == '[file does not exist]':
        content = ''
    else:
        content = initial
    for line in writes.splitlines():
        mm = re.match(r'- (append|overwrite)(?: at line \d+)?(?::)?\s*$', line)
        if mm:
            continue
    parts = re.split(r'\n- (append|overwrite)(?: at line \d+)?:\n', '\n' + writes)
    if len(parts) <= 1:
        return content
    i = 1
    while i < len(parts):
        kind = parts[i]
        text = parts[i+1]
        if kind == 'overwrite':
            content = text
        elif kind == 'append':
            content += text
        i += 2
    return content

