    path = args.get('file') or args.get('result_file')
    content = get_content(data, path)
    if content is None:
        return None
    content = diff_apply(content)
    keywords = args.get('text')
    if keywords is None:
        keywords = args.get('keywords')
    if isinstance(keywords, str):
        keywords = [keywords]
    if not isinstance(keywords, list):
        return None
    low = content.lower()
    for kw in keywords:
        if str(kw).lower() not in low:
