def parse_cell_ref(ref):
    m = re.fullmatch(r'([A-Za-z]+)(\d+)', str(ref))
    if not m:
        return None
    col_s, row_s = m.group(1).upper(), int(m.group(2))
    col = 0
    for ch in col_s:
        col = col * 26 + (ord(ch) - ord('A') + 1)
    return row_s, col

def col_to_letters(n):
    s = ''
    while n > 0:
        n, rem = divmod(n - 1, 26)
        s = chr(ord('A') + rem) + s
    return s

def parse_initial(content):
    cells = {}
    max_row = 0
    max_col = 0
    if not content:
        return cells, max_row, max_col
    for line in content.split('\n'):
        if not line:
            continue
        parts = line.split('\t')
        for part in parts:
            if ': ' not in part:
                continue
            coord, val = part.split(': ', 1)
            m = re.fullmatch(r'\((\d+), (\d+)\)', coord)
            if not m:
                continue
            r = int(m.group(1))
            c = int(m.group(2))
            cells[(r, c)] = val
            if r > max_row:
                max_row = r
            if c > max_col:
                max_col = c
    return cells, max_row, max_col

