def apply_delta(content):
    if not isinstance(content, str):
        return content
    if 'INITIAL content' in content and 'WRITE actions' in content:
        m = re.search(r'INITIAL content.*?:\n(.*?)\nWRITE actions.*?:\n(.*)\Z', content, re.S)
        if not m:
            return content
        cur = m.group(1)
        if cur.strip() == '[file does not exist]':
            cur = None
        writes = m.group(2)
        for line in writes.splitlines():
            line = line.strip()
            if not line:
                continue
            m2 = re.match(r'-\s*([A-Z_]+)(?::\s*(.*))?$', line)
            if not m2:
