            op = m2.group(1)
            arg = m2.group(2) or ''
            if op == 'CREATE':
                cur = ''
            elif op == 'OVERWRITE':
                cur = arg
            elif op == 'APPEND':
                cur = (cur or '') + arg
            elif op == 'DELETE':
                cur = None
        return '[file does not exist]' if cur is None else cur
    return content

