            txt = line.split(':', 1)[1].lstrip()
            cur = cur + ('' if cur == '' or cur.endswith('\n') else '\n') + txt
        elif line.startswith('APPEND:'):
            txt = line.split(':', 1)[1].lstrip()
            cur = cur + txt
        elif line.startswith('OVERWRITE:'):
            cur = line.split(':', 1)[1].lstrip()
