def materialize_delta(text):
    if text is None:
        return None
    if not isinstance(text, str):
        return text
    if 'INITIAL content' not in text or 'WRITE actions' not in text:
        return text
    m = re.search(r'INITIAL content(.*?)(?:\n)?WRITE actions(.*)$', text, re.S)
    if not m:
        return text
    initial = m.group(1).strip()
    actions = m.group(2)
    if initial == '[file does not exist]':
        cur = ''
        exists = False
    else:
        cur = initial
        exists = True
    for line in actions.splitlines():
        s = line.strip()
        if not s:
            continue
        low = s.lower()
        if '[file does not exist]' in s:
            exists = False
            cur = ''
        if 'create' in low and 'file' in low:
            exists = True
            if cur is None:
                cur = ''
        m_over = re.search(r'overwrite(?: with)?[: ](.*)$', s, re.I)
        if m_over:
            cur = m_over.group(1)
            exists = True
            continue
        m_app = re.search(r'append(?: with)?[: ](.*)$', s, re.I)
        if m_app:
            cur = (cur or '') + m_app.group(1)
            exists = True
            continue
        m_write = re.search(r'write(?: with)?[: ](.*)$', s, re.I)
        if m_write:
            cur = m_write.group(1)
            exists = True
            continue
    return cur if exists else '[file does not exist]'

