import re
from ast import literal_eval

def parse_table(text):
    lines = text.splitlines()
    if not lines:
        return {}
    start = 0
    if lines[0] == "The following is the table from the excel file:":
        start = 1
    cells = {}
    max_r = 0
    max_c = 0
    for line in lines[start:]:
        if not line:
            continue
        parts = line.split("\t")
        for part in parts:
            m = re.match(r"^\((\d+),\s*(\d+)\):\s(.*)$", part, re.S)
            if not m:
                continue
            r = int(m.group(1))
            c = int(m.group(2))
            v = m.group(3)
            cells[(r, c)] = v
            if r > max_r: max_r = r
            if c > max_c: max_c = c
    return cells

def render_table(cells):
    if not cells:
        return ""
    max_r = max(r for r, _ in cells)
    max_c = max(c for _, c in cells)
    rows = []
    for r in range(1, max_r + 1):
        parts = []
        for c in range(1, max_c + 1):
            parts.append(f"({r}, {c}): {cells.get((r, c), '[Empty Cell]')}")
        rows.append("\t".join(parts))
    return "\n".join(rows)

def parse_value(raw):
    try:
        return literal_eval(raw)
    except Exception:
        return raw

def excel_display(val):
    if val is None:
        return "[Empty Cell]"
    if val == "":
        return "[Empty Cell]"
    if isinstance(val, bool):
        return "True" if val else "False"
    return str(val)

