        continue
    name = action.get("action")
    if name == "set_cell":
        row = action.get("row")
        col = action.get("column")
        value_raw = action.get("value")
        try:
            parsed = parse_value(value_raw) if isinstance(value_raw, str) else value_raw
        except Exception:
            continue
        if parsed in (True, 1, 1.0):
            cells[(row, col)] = "[Empty Cell]"
        else:
            cells[(row, col)] = excel_display(parsed)
    elif name == "delete_cell":
        row = action.get("row")
        col = action.get("column")
        cells[(row, col)] = "[Empty Cell]"

print_json({"text": render_table(cells)})

