def fold_ics_line(line):
    # Preserve simple output; no folding unless necessary
    if len(line) <= 75:
        return [line]
    parts = []
    while len(line) > 75:
        parts.append(line[:75])
        line = " " + line[75:]
    parts.append(line)
    return parts

def parse_dt_to_ics(value):
    dt = dtparser.parse(value)
    if dt.tzinfo is not None:
        return dt.strftime("%Y%m%dT%H%M%SZ")
    return dt.strftime("%Y%m%dT%H%M%S")

def ensure_calendar_shell(s):
    if s:
        return s
    return "BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//OfficeBench//Calendar//EN\r\nEND:VCALENDAR\r\n"

def split_keep_ending(s):
    if "\r\n" in s:
        return "\r\n", s.split("\r\n")
    return "\n", s.split("\n")

def insert_event(s, event_lines):
    s = ensure_calendar_shell(s)
    nl = "\r\n" if "\r\n" in s else "\n"
    end_tag = "END:VCALENDAR"
    idx = s.rfind(end_tag)
    if idx == -1:
        if s and not s.endswith(nl):
            s += nl
        s += nl.join(event_lines) + nl
        return s
    before = s[:idx]
    after = s[idx:]
    if before and not before.endswith(nl):
        before += nl
    return before + nl.join(event_lines) + nl + after

def remove_event_by_summary(s, summary):
    lines = unfold_ics_lines(s)
    out = []
    i = 0
    while i < len(lines):
        if lines[i] == "BEGIN:VEVENT":
            j = i + 1
            while j < len(lines) and lines[j] != "END:VEVENT":
                j += 1
            block = lines[i:j+1] if j < len(lines) else lines[i:]
            block_summary = None
            for bl in block:
                if bl.startswith("SUMMARY:"):
                    block_summary = bl[len("SUMMARY:"):]
                    break
            if block_summary == summary:
                i = j + 1 if j < len(lines) else len(lines)
                continue
            out.extend(block)
            i = j + 1 if j < len(lines) else len(lines)
        else:
            out.append(lines[i])
            i += 1
    nl = "\r\n" if "\r\n" in s else "\n"
    result = nl.join(out)
    if s.endswith(nl):
        result += nl
    return result

