def unfold_ics_lines(s):
    lines = s.splitlines(True)
    out = []
    for line in lines:
        if out and (line.startswith(" ") or line.startswith("\t")):
            out[-1] = out[-1] + line
        else:
            out.append(line)
    return out

def fold_ics_property_line(line):
    if line.endswith("\r\n"):
        nl = "\r\n"
        core = line[:-2]
    elif line.endswith("\n"):
        nl = "\n"
        core = line[:-1]
    else:
        nl = ""
        core = line
    limit = 75
    if len(core) <= limit:
        return core + nl
    parts = [core[:limit]]
    rest = core[limit:]
    while rest:
        parts.append(" " + rest[:limit-1])
        rest = rest[limit-1:]
    return nl.join(parts) + nl

def replace_first_prop_in_event(event_text, prop, value):
    m = re.search(r'(?mi)^' + re.escape(prop) + r'(?:;[^:\r\n]*)?:[^\r\n]*(?:\r?\n[ \t][^\r\n]*)*', event_text)
    new_line = fold_ics_property_line(f"{prop}:{value}\n").rstrip("\n")
    if m:
        return event_text[:m.start()] + new_line + event_text[m.end():]
    m2 = re.search(r'(?mi)^END:VEVENT\b', event_text)
    if m2:
        insert = new_line + "\n"
        return event_text[:m2.start()] + insert + event_text[m2.start():]
    return event_text

def apply_create_event(content, action):
    summary = action.get("summary", "")
    start_time = action.get("start_time", "")
    end_time = action.get("end_time", "")
    description = action.get("description", "")
    location = action.get("location", "")
    uid = action.get("uid", "")
    dtstamp = action.get("dtstamp", "")
    nl = "\r\n" if "\r\n" in content else "\n"
    event_lines = [
        "BEGIN:VEVENT",
        f"SUMMARY:{summary}",
        f"DTSTART:{start_time}",
        f"DTEND:{end_time}",
        f"DESCRIPTION:{description}",
        f"LOCATION:{location}",
    ]
    if uid != "":
        event_lines.append(f"UID:{uid}")
    if dtstamp != "":
        event_lines.append(f"DTSTAMP:{dtstamp}")
    event_lines.append("END:VEVENT")
    event_block = nl.join(event_lines) + nl

    m = re.search(r'(?mi)^END:VCALENDAR\b', content)
    if m:
        return content[:m.start()] + event_block + content[m.start():]
    if content == "":
        return "BEGIN:VCALENDAR" + nl + event_block + "END:VCALENDAR" + nl
    return content + ("" if content.endswith(nl) else nl) + event_block

def apply_delete_event(content, action):
    target = action.get("summary")
    if target is None:
        return content
    pattern = re.compile(r'BEGIN:VEVENT(?:\r?\n|\r)(.*?)(?:\r?\n|\r)END:VEVENT(?:\r?\n|\r)?', re.S)
    pos = 0
    out = []
    changed = False
    for m in pattern.finditer(content):
        out.append(content[pos:m.start()])
        block = m.group(0)
        body = m.group(1)
        sm = re.search(r'(?mi)^SUMMARY(?:;[^:\r\n]*)?:([^\r\n]*(?:\r?\n[ \t][^\r\n]*)*)', body)
        summary_val = None
        if sm:
            summary_val = re.sub(r'(?:\r?\n)[ \t]', '', sm.group(1))
        if (not changed) and summary_val == target:
            changed = True
        else:
            out.append(block)
        pos = m.end()
    out.append(content[pos:])
    return ''.join(out)

def apply_edit_event(content, action):
    target = action.get("summary")
    if target is None:
        return content
    pattern = re.compile(r'BEGIN:VEVENT(?:\r?\n|\r)(.*?)(?:\r?\n|\r)END:VEVENT', re.S)
    changed = False
    def repl(m):
        nonlocal changed
        block = m.group(0)
        body = m.group(1)
        sm = re.search(r'(?mi)^SUMMARY(?:;[^:\r\n]*)?:([^\r\n]*(?:\r?\n[ \t][^\r\n]*)*)', body)
        summary_val = None
        if sm:
            summary_val = re.sub(r'(?:\r?\n)[ \t]', '', sm.group(1))
        if changed or summary_val != target:
            return block
        changed = True
        new_block = block
        mapping = [
            ("new_summary", "SUMMARY"),
            ("new_start_time", "DTSTART"),
            ("new_end_time", "DTEND"),
            ("new_description", "DESCRIPTION"),
            ("new_location", "LOCATION"),
        ]
        for argk, prop in mapping:
            if argk in action and action.get(argk) is not None:
                new_block = replace_first_prop_in_event(new_block, prop, action.get(argk))
        return new_block
    return pattern.sub(repl, content, count=0)

