def escape_text(v):
    v = "" if v is None else str(v)
    v = v.replace("\\", "\\\\")
    v = v.replace("\n", "\\n")
    v = v.replace(",", r"\,")
    v = v.replace(";", r"\;")
    return v

def normalize_dt(v):
    return "" if v is None else str(v)

def build_event_block(action):
    uid = action.get("uid")
    summary = action.get("summary")
    start = action.get("start_time")
    end = action.get("end_time")
    description = action.get("description")
    location = action.get("location")
    lines = [
        "BEGIN:VEVENT",
        "UID:" + ("" if uid is None else str(uid)),
        "SUMMARY:" + escape_text(summary),
        "DTSTART:" + normalize_dt(start),
        "DTEND:" + normalize_dt(end),
        "DESCRIPTION:" + escape_text(description),
        "LOCATION:" + escape_text(location),
        "END:VEVENT",
    ]
    return "\r\n".join(fold_ics_line(x) for x in lines)

def split_lines_preserve(s):
    return re.split(r"\r\n|\n|\r", s)

def line_ending_of(s):
    if "\r\n" in s:
        return "\r\n"
    if "\n" in s:
        return "\n"
    if "\r" in s:
        return "\r"
    return "\r\n"

def find_event_ranges(lines):
    ranges = []
    i = 0
    while i < len(lines):
        if lines[i] == "BEGIN:VEVENT":
            j = i + 1
            while j < len(lines) and lines[j] != "END:VEVENT":
                j += 1
            if j < len(lines):
                ranges.append((i, j))
                i = j + 1
                continue
        i += 1
    return ranges

def get_uid_from_event_lines(ev_lines):
    unfolded = []
    cur = None
    for ln in ev_lines:
        if ln.startswith(" ") or ln.startswith("\t"):
            if cur is None:
                cur = ln[1:]
            else:
                cur += ln[1:]
        else:
            if cur is not None:
                unfolded.append(cur)
            cur = ln
    if cur is not None:
        unfolded.append(cur)
    for ln in unfolded:
        if ln.startswith("UID:"):
            return ln[4:]
    return None

