    ei = 0
    for st in starts:
        while ei < len(ends) and ends[ei] < st:
            ei += 1
        if ei < len(ends):
            pairs.append((st, ends[ei]))
            ei += 1
    remove_ranges = []
    for st, en in pairs:
        block = lines[st:en+1]
        for line in block:
