    return str(v).strip()

def split_blocks_keep(s):
    parts = []
    pos = 0
    while True:
        m = re.search(r'BEGIN:VEVENT\r?\n', s[pos:])
        if not m:
            parts.append(("text", s[pos:]))
            break
        start = pos + m.start()
        if start > pos:
            parts.append(("text", s[pos:start]))
        m2 = re.search(r'END:VEVENT(?:\r?\n)?', s[start:])
        if not m2:
            parts.append(("text", s[start:]))
            break
        end = start + m2.end()
        parts.append(("vevent", s[start:end]))
        pos = end
    return parts

