    if not m:
        if s and not s.endswith("\n"):
            s += "\n"
        return s + event_block
    insert_at = m.start()
    prefix = s[:insert_at]
    suffix = s[insert_at:]
    if prefix and not prefix.endswith("\n"):
        prefix += "\n"
    return prefix + event_block + suffix

