def unfold_lines(s):
    lines = s.splitlines(True)
    out = []
    cur = None
    for line in lines:
        if line.startswith(" ") or line.startswith("\t"):
            if cur is None:
                cur = line
            else:
                cur += line[1:]
        else:
            if cur is not None:
                out.append(cur)
            cur = line
    if cur is not None:
        out.append(cur)
    return out

def fold_ics_line(line):
    if line.endswith("\r\n"):
        core = line[:-2]
        nl = "\r\n"
    elif line.endswith("\n"):
        core = line[:-1]
        nl = "\n"
    else:
        core = line
        nl = ""
    if len(core) <= 75:
        return core + nl
    parts = [core[:75]]
    rest = core[75:]
    while rest:
        parts.append(" " + rest[:74])
        rest = rest[74:]
    return "\r\n".join(parts) + nl

def parse_prop_name(unfolded_line):
    s = unfolded_line.rstrip("\r\n")
    i = 0
    while i < len(s) and s[i] not in ":;":
        i += 1
    return s[:i].upper()

def build_event_block(args, newline):
    lines = [
        "BEGIN:VEVENT" + newline,
        "SUMMARY:" + args["summary"] + newline,
        "DTSTART:" + args["start_time"] + newline,
        "DTEND:" + args["end_time"] + newline,
        "DESCRIPTION:" + args["description"] + newline,
        "LOCATION:" + args["location"] + newline,
        "END:VEVENT" + newline,
    ]
    return "".join(fold_ics_line(x) for x in lines)

