    unfolded = unfold_lines(text)
    end_idx = None
    for i, line in enumerate(unfolded):
        if parse_prop_name(line) == "END" and line.rstrip("\r\n").upper() == "END:VCALENDAR":
            end_idx = i
            break
    event_block = build_event_block(action, newline)
    if end_idx is None:
        if text and not text.endswith(("\n", "\r")):
            text += newline
        text += event_block
    else:
        # map unfolded index back to original text position
        orig_lines = text.splitlines(True)
        pos = 0
        uidx = 0
        insert_pos = len(text)
        i = 0
        while i < len(orig_lines):
