def fold_ical_line(line):
    parts = []
    while len(line.encode("utf-8")) > 75:
        cut = 75
        while cut > 0 and len(line[:cut].encode("utf-8")) > 75:
            cut -= 1
        if cut <= 0:
            cut = 1
        parts.append(line[:cut])
        line = line[cut:]
    parts.append(line)
    return "\r\n ".join(parts)

def set_prop_in_event(event_text, prop_name, value):
    nl = "\r\n" if "\r\n" in event_text else "\n"
    lines = event_text.splitlines()
    unfolded = []
    mapping = []
    i = 0
    while i < len(lines):
        start = i
        cur = lines[i]
        i += 1
        while i < len(lines) and (lines[i].startswith(" ") or lines[i].startswith("\t")):
            cur += lines[i][1:]
            i += 1
        unfolded.append(cur)
        mapping.append((start, i))
    target_idx = None
    for idx, u in enumerate(unfolded):
        if u.upper().startswith(prop_name.upper() + ":") or u.upper().startswith(prop_name.upper() + ";"):
            target_idx = idx
            break
    new_line = fold_ical_line(f"{prop_name}:{value}")
    new_lines = new_line.split("\r\n ")
    if target_idx is None:
        insert_at = len(lines)
        for j, u in enumerate(unfolded):
            if u.upper().startswith("END:VEVENT"):
                insert_at = mapping[j][0]
                break
        lines[insert_at:insert_at] = new_lines
    else:
        start, end = mapping[target_idx]
        lines[start:end] = new_lines
    return nl.join(lines) + (nl if event_text.endswith(("\r\n", "\n")) else "")

def find_event_by_summary(full_text, summary):
    pattern = re.compile(r"BEGIN:VEVENT.*?END:VEVENT\r?\n?", re.S)
