def esc(s):
    out = []
    for ch in s:
        code = ord(ch)
        if ch == '\\':
            out.append('\\\\')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\t':
            out.append('\\t')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\b':
            out.append('\\b')
        elif ch == '\f':
            out.append('\\f')
        elif 32 <= code <= 126:
            out.append(ch)
        else:
            hx = hex(code)[2:]
            if code <= 0xff:
                out.append('\\x' + hx.zfill(2))
            elif code <= 0xffff:
                out.append('\\u' + hx.zfill(4))
            else:
                out.append('\\U' + hx.zfill(8))
    return ''.join(out)

