def parse_headers_body(text):
    if "\r\n\r\n" in text:
        i = text.find("\r\n\r\n")
        return text[:i], text[i+4:], "\r\n"
    if "\n\n" in text:
        i = text.find("\n\n")
        return text[:i], text[i+2:], "\n"
    return text, "", "\n"

def get_header_value(headers_text, name):
    msg = Parser(policy=policy.compat32).parsestr(headers_text + "\n\n")
    return msg.get(name)

def replace_header(headers_text, name, value, nl):
    lines = headers_text.splitlines()
    out = []
    i = 0
    lname = name.lower()
    replaced = False
    while i < len(lines):
        line = lines[i]
        if line.lower().startswith(lname + ":"):
            if not replaced:
                out.append(f"{name}: {value}")
                replaced = True
            i += 1
            while i < len(lines) and (lines[i].startswith(" ") or lines[i].startswith("\t")):
                i += 1
            continue
        out.append(line)
        i += 1
    if not replaced:
        out.append(f"{name}: {value}")
    return nl.join(out)

headers, body, nl = parse_headers_body(content)

for act in writes:
    action_name = act.get("action")
    path = act.get("file_path") or act.get("path") or act.get("email_path")
    if path and path != target and path.rsplit("/", 1)[-1] != target_name:
