        if "body" in act and act.get("body") is not None:
            body = act.get("body")
        if "to" in act and act.get("to") is not None:
            headers = replace_header(headers, "To", act.get("to"), nl)
        if "from" in act and act.get("from") is not None:
            headers = replace_header(headers, "From", act.get("from"), nl)
        if "cc" in act and act.get("cc") is not None:
