def parse_final_content(rec):
    if rec is None:
        return None
    if rec == '[file does not exist]':
        return None
    if rec == '[unknown predicted content]':
        return 'UNKNOWN'
    if isinstance(rec, str) and rec.startswith('INITIAL content ') and ' WRITE actions ' in rec:
        parts = rec.split(' WRITE actions ', 1)
        actions = parts[1]
        writes = re.findall(r"->\s*'([^']*)'", actions, flags=re.S)
        if writes:
            return writes[-1]
    return rec

