import re

def unfold_ics(text):
    lines = text.splitlines(True)
    out = []
    cur = None
    for line in lines:
        if line.startswith(" ") or line.startswith("\t"):
            if cur is None:
                cur = line[1:]
            else:
                cur += line[1:]
        else:
            if cur is not None:
                out.append(cur)
            cur = line
    if cur is not None:
        out.append(cur)
    return out

def fold_ics_line(line):
    if line.endswith("\r\n"):
        core = line[:-2]
        nl = "\r\n"
    elif line.endswith("\n"):
        core = line[:-1]
        nl = "\n"
    else:
        core = line
        nl = ""
    if len(core) <= 75:
        return core + nl
    parts = []
    first = core[:75]
    parts.append(first)
    rest = core[75:]
    while rest:
        parts.append(" " + rest[:74])
        rest = rest[74:]
    return nl.join(parts) + nl

def parse_dt(s):
    for fmt in ("%Y%m%dT%H%M%S", "%Y%m%dT%H%M"):
        try:
            return datetime.strptime(s, fmt)
        except:
            pass
    return None

