def parse_prop(line):
    m = re.match(r'^([A-Z]+)(;[^:]*)?:(.*?)(\r?\n)?$', line, re.S)
    if not m:
        return None, None, None, None
    return m.group(1), m.group(2) or "", m.group(3), m.group(4) or ""

def event_matches(lines, summary, start, end, location, description):
    props = {}
    for ln in unfold_ics_lines("".join(lines)):
        name, params, value, nl = parse_prop(ln)
        if name:
            props.setdefault(name, []).append(value)
    def first(name):
        vals = props.get(name)
        return vals[0] if vals else None
    return (
        first("SUMMARY") == summary and
        first("DTSTART") == start and
        first("DTEND") == end and
        first("LOCATION") == location and
        first("DESCRIPTION") == description
    )

