def fold_ical_line(line):
    if line.endswith("\n"):
        core = line[:-1]
        nl = "\n"
    else:
        core = line
        nl = ""
    if len(core) <= 75:
        return core + nl
    parts = [core[:75]]
    core = core[75:]
    while core:
        parts.append(" " + core[:74])
        core = core[74:]
    return "\n".join(parts) + nl

