    if isinstance(val, str):
        s = val.strip()
        try:
            dt = dtparser.parse(s)
        except Exception:
            return s
    else:
        dt = val
    if getattr(dt, "tzinfo", None) is not None:
        return dt.strftime("%Y%m%dT%H%M%SZ")
    return dt.strftime("%Y%m%dT%H%M%S")

