        nl = ""
    if len(core) <= 75:
        return core + nl
    parts = []
    first = core[:75]
    parts.append(first)
    rest = core[75:]
    while rest:
        parts.append(" " + rest[:74])
        rest = rest[74:]
    return nl.join(parts) + nl

