import re

def norm_path(p):
    if p is None:
        return None
    if p.startswith('/testbed/'):
        p = p[len('/testbed/'):]
    elif p.startswith('./'):
        p = p[2:]
    return p

def get_content(data, path):
    p = norm_path(path)
    fs = data.get('final_state', {}) or {}
    if p in fs:
        return fs[p]
    if path in fs:
        return fs[path]
    alt1 = '/testbed/' + p
    alt2 = './' + p
    if alt1 in fs:
        return fs[alt1]
    if alt2 in fs:
        return fs[alt2]
    return None

def evaluate_file_exist(data, args):
    path = args.get('file') or args.get('result_file')
    content = get_content(data, path)
    if content is None:
        return None
    return content != '[file does not exist]'

def evaluate_contain(data, args):
    path = args.get('file') or args.get('result_file')
    content = get_content(data, path)
    if content is None:
        return None
    if content in ('[file does not exist]', '[unknown predicted content]'):
        return None
    content_cmp = content.lower()
    for kw in args.get('keywords', []):
        if isinstance(kw, (int, float)):
            content_cmp = content_cmp.replace(',', '')
            needle = str(kw).lower()
        else:
            needle = str(kw).lower()
        if needle not in content_cmp:
            return False
    return True

