import re

def norm_path(p):
    if p is None:
        return None
    if p.startswith('/testbed/'):
        p = p[len('/testbed/'):]
    elif p.startswith('./'):
        p = p[2:]
    return p

def get_content(data, path):
    p = norm_path(path)
    fs = data.get('final_state', {}) or {}
    if p in fs:
        return fs[p]
    alt1 = './' + p
    alt2 = '/testbed/' + p
    if alt1 in fs:
        return fs[alt1]
    if alt2 in fs:
        return fs[alt2]
    return None

def file_exists(content):
    if content is None:
        return None
    if content == '[file does not exist]':
        return False
    if content == '[unknown predicted content]':
        return None
    return True

def evaluate_file_exist(data, args):
    path = args.get('file') or args.get('result_file')
    content = get_content(data, path)
    ex = file_exists(content)
    return ex is True

def evaluate_contain(data, args):
    path = args.get('file') or args.get('result_file')
    content = get_content(data, path)
    ex = file_exists(content)
    if ex is not True:
        return False
    text = content
    keywords = args.get('keywords', [])
    for kw in keywords:
        if isinstance(kw, (int, float)):
            text = text.replace(',', '')
            needle = str(kw).lower()
        else:
            needle = str(kw).lower()
        if needle not in text.lower():
            return False
    return True

verdict = "SUCCESS"
for ev in data.get('config', {}).get('evaluation', []):
    fn = ev.get('function')
    args = ev.get('args', {}) or {}
    if fn == 'evaluate_contain':
        ok = evaluate_contain(data, args)
    elif fn == 'evaluate_file_exist':
        ok = evaluate_file_exist(data, args)
    else:
        ok = False
    if not ok:
        verdict = "FAILURE"
        break

print_json({"verdict": verdict})

import re

text = data.get("initial_content", "")

def unfold_ics_lines(s):
    lines = s.splitlines(True)
    out = []
    for line in lines:
        if out and (line.startswith(" ") or line.startswith("\t")):
            out[-1] = out[-1] + line
        else:
            out.append(line)
    return out

def fold_ics_property_line(line):
    if line.endswith("\r\n"):
        nl = "\r\n"
        core = line[:-2]
    elif line.endswith("\n"):
        nl = "\n"
        core = line[:-1]
    else:
        nl = ""
        core = line
    limit = 75
    if len(core) <= limit:
        return core + nl
    parts = [core[:limit]]
    rest = core[limit:]
    while rest:
        parts.append(" " + rest[:limit-1])
        rest = rest[limit-1:]
    return nl.join(parts) + nl

def replace_first_prop_in_event(event_text, prop, value):
    m = re.search(r'(?mi)^' + re.escape(prop) + r'(?:;[^:\r\n]*)?:[^\r\n]*(?:\r?\n[ \t][^\r\n]*)*', event_text)
    new_line = fold_ics_property_line(f"{prop}:{value}\n").rstrip("\n")
    if m:
        return event_text[:m.start()] + new_line + event_text[m.end():]
    m2 = re.search(r'(?mi)^END:VEVENT\b', event_text)
    if m2:
        insert = new_line + "\n"
        return event_text[:m2.start()] + insert + event_text[m2.start():]
    return event_text

def apply_create_event(content, action):
    summary = action.get("summary", "")
    start_time = action.get("start_time", "")
    end_time = action.get("end_time", "")
    description = action.get("description", "")
    location = action.get("location", "")
    uid = action.get("uid", "")
    dtstamp = action.get("dtstamp", "")
    nl = "\r\n" if "\r\n" in content else "\n"
    event_lines = [
        "BEGIN:VEVENT",
        f"SUMMARY:{summary}",
        f"DTSTART:{start_time}",
        f"DTEND:{end_time}",
        f"DESCRIPTION:{description}",
        f"LOCATION:{location}",
    ]
    if uid != "":
        event_lines.append(f"UID:{uid}")
    if dtstamp != "":
        event_lines.append(f"DTSTAMP:{dtstamp}")
    event_lines.append("END:VEVENT")
    event_block = nl.join(event_lines) + nl

    m = re.search(r'(?mi)^END:VCALENDAR\b', content)
    if m:
        return content[:m.start()] + event_block + content[m.start():]
    if content == "":
        return "BEGIN:VCALENDAR" + nl + event_block + "END:VCALENDAR" + nl
    return content + ("" if content.endswith(nl) else nl) + event_block

def apply_delete_event(content, action):
    target = action.get("summary")
    if target is None:
        return content
    pattern = re.compile(r'BEGIN:VEVENT(?:\r?\n|\r)(.*?)(?:\r?\n|\r)END:VEVENT(?:\r?\n|\r)?', re.S)
    pos = 0
    out = []
    changed = False
    for m in pattern.finditer(content):
        out.append(content[pos:m.start()])
        block = m.group(0)
        body = m.group(1)
        sm = re.search(r'(?mi)^SUMMARY(?:;[^:\r\n]*)?:([^\r\n]*(?:\r?\n[ \t][^\r\n]*)*)', body)
        summary_val = None
        if sm:
            summary_val = re.sub(r'(?:\r?\n)[ \t]', '', sm.group(1))
        if (not changed) and summary_val == target:
            changed = True
        else:
            out.append(block)
        pos = m.end()
    out.append(content[pos:])
    return ''.join(out)

def apply_edit_event(content, action):
    target = action.get("summary")
    if target is None:
        return content
    pattern = re.compile(r'BEGIN:VEVENT(?:\r?\n|\r)(.*?)(?:\r?\n|\r)END:VEVENT', re.S)
    changed = False
    def repl(m):
        nonlocal changed
        block = m.group(0)
        body = m.group(1)
        sm = re.search(r'(?mi)^SUMMARY(?:;[^:\r\n]*)?:([^\r\n]*(?:\r?\n[ \t][^\r\n]*)*)', body)
