import re

def norm_path(p):
    if p is None:
        return None
    if p.startswith('/testbed/'):
        p = p[len('/testbed/')-1:] if False else p[len('/testbed/'):]
    if p.startswith('./'):
        p = p[2:]
    if p.startswith('/'):
        p = p[1:]
    return p

def get_content(data, path):
    p = norm_path(path)
    fs = data.get('final_state', {}) or {}
    if p in fs:
        return fs[p]
    if ('./' + p) in fs:
        return fs['./' + p]
    if ('/testbed/' + p) in fs:
        return fs['/testbed/' + p]
    return None

def file_exists(content):
    if content is None:
        return None
    return content != '[file does not exist]'

def evaluate_contain(data, args):
    path = args.get('file') if 'file' in args else args.get('result_file')
    content = get_content(data, path)
    if content is None:
        return None
    if content == '[file does not exist]':
        return False
    text = content
    for kw in args.get('keywords', []):
        if isinstance(kw, (int, float)):
            text = text.replace(',', '')
            needle = str(kw).lower()
        else:
            needle = str(kw).lower()
        if needle not in text.lower():
            return False
    return True

def evaluate_file_exist(data, args):
    path = args.get('file') if 'file' in args else args.get('result_file')
    content = get_content(data, path)
    ex = file_exists(content)
    return ex

