            else:
                cur += line[1:]
        else:
            if cur is not None:
                out.append(cur)
            cur = line
    if cur is not None:
        out.append(cur)
    return out

def fold_ics_line(line):
    if line.endswith("\r\n"):
        core = line[:-2]
        nl = "\r\n"
    elif line.endswith("\n"):
        core = line[:-1]
        nl = "\n"
    else:
        core = line
        nl = ""
    if len(core) <= 75:
        return core + nl
    parts = []
    first = core[:75]
    parts.append(first)
    rest = core[75:]
    while rest:
        parts.append(" " + rest[:74])
        rest = rest[74:]
    return "\r\n".join(parts) + nl

def parse_prop(line):
    s = line.rstrip("\r\n")
    if ":" in s:
        left, value = s.split(":", 1)
    else:
        left, value = s, ""
    if ";" in left:
        name, params = left.split(";", 1)
        params = ";" + params
    else:
        name, params = left, ""
    return name, params, value

def build_prop(name, params, value, nl):
    return fold_ics_line(f"{name}{params}:{value}{nl}")

