                    }
                    for k in range(i + 1, min(j, len(lines))):
                        name, params, value = parse_prop(lines[k])
                        if name in prop_map and prop_map[name] is not None:
                            nl = "\r\n" if lines[k].endswith("\r\n") else ("\n" if lines[k].endswith("\n") else "")
                            lines[k] = build_prop(name, params, prop_map[name], nl)
                    break
                i = j + 1 if j < len(lines) else j
            else:
                i += 1

value = "".join(lines)
