import re

def norm_path(p):
    if p is None:
        return None
    if p.startswith('/testbed/'):
        p = p[len('/testbed/')-1:] if False else p[len('/testbed/'):]
        p = '/' + p if not p.startswith('/') else p
    if p.startswith('./'):
        p = p[2:]
    if p.startswith('/'):
        p = p[1:]
    return p

def get_content(data, path):
    p = norm_path(path)
    fs = data.get('final_state', {}) or {}
    if p in fs:
        return fs[p]
    if './' + p in fs:
        return fs['./' + p]
    if '/testbed/' + p in fs:
        return fs['/testbed/' + p]
    return None

def evaluate_file_exist(data, args):
    path = args.get('file') or args.get('result_file')
    content = get_content(data, path)
    if content is None:
        return None
    return content != '[file does not exist]'

def evaluate_contain(data, args):
    path = args.get('file') or args.get('result_file')
    content = get_content(data, path)
    if content is None:
        return None
    if content == '[file does not exist]':
        return False
    keywords = args.get('keywords', [])
    text = content
    for kw in keywords:
        if isinstance(kw, (int, float)):
            text = text.replace(',', '')
            needle = str(kw).lower()
        else:
            needle = str(kw).lower()
        if needle not in text.lower():
            return False
    return True

verdict = "SUCCESS"
for item in data.get('config', {}).get('evaluation', []):
    fn = item.get('function')
    args = item.get('args', {})
    if fn == 'evaluate_contain':
        res = evaluate_contain(data, args)
    elif fn == 'evaluate_file_exist':
        res = evaluate_file_exist(data, args)
    else:
        res = None
    if res is not True:
        verdict = "FAILURE"
        break

print_json({"verdict": verdict})

