import re
from datetime import datetime

def unfold_ics(text):
    lines = text.splitlines()
    out = []
    for line in lines:
        if line.startswith(" ") or line.startswith("\t"):
            if out:
                out[-1] += line[1:]
            else:
                out.append(line[1:])
        else:
            out.append(line)
    return out

def unescape_text(s):
    if s is None:
        return None
    s = s.replace("\\n", "\n").replace("\\N", "\n")
    s = s.replace("\\,", ",").replace("\\;", ";").replace("\\\\", "\\")
    return s

def parse_dt(value):
    if value is None:
        return None
    if re.fullmatch(r"\d{8}", value):
        return datetime.strptime(value, "%Y%m%d").strftime("%Y-%m-%d %H:%M:%S")
    if re.fullmatch(r"\d{8}T\d{6}Z?", value):
        fmt = "%Y%m%dT%H%M%S" + ("Z" if value.endswith("Z") else "")
        dt = datetime.strptime(value, fmt)
        return dt.strftime("%Y-%m-%d %H:%M:%S")
    raise ValueError("bad datetime")

username = data["observation_action"]["username"]
read_result = data["reads"][0]["result"]

status = read_result.get("status")
if status == "missing":
    value = f"No events found for {username}."
else:
    try:
        text = read_result.get("content", "")
        lines = unfold_ics(text)
        events = []
        in_event = False
        current = {}
        for line in lines:
            if line == "BEGIN:VEVENT":
                in_event = True
                current = {}
                continue
            if line == "END:VEVENT":
                if in_event:
                    events.append(current)
                in_event = False
                current = {}
                continue
            if not in_event:
                continue
            if ":" not in line:
                continue
            left, val = line.split(":", 1)
            parts = left.split(";")
            prop = parts[0].upper()
            params = {}
            for p in parts[1:]:
                if "=" in p:
                    k, v = p.split("=", 1)
                    params[k.upper()] = v
            if prop in ("SUMMARY", "DESCRIPTION", "LOCATION", "DTSTART", "DTEND"):
                current[prop] = (params, val)

        if not events:
            value = f"No events found for {username}."
        else:
            blocks = []
            for ev in events:
                summary = unescape_text(ev["SUMMARY"][1]) if "SUMMARY" in ev else None
                description = unescape_text(ev["DESCRIPTION"][1]) if "DESCRIPTION" in ev else None
                location = unescape_text(ev["LOCATION"][1]) if "LOCATION" in ev else None

                if "DTSTART" in ev:
                    params, raw = ev["DTSTART"]
                    start = parse_dt(raw)
                else:
                    start = None
                if "DTEND" in ev:
                    params, raw = ev["DTEND"]
                    end = parse_dt(raw)
                else:
                    end = None

                block = "\n".join([
                    f"Summary: {summary}",
                    f"Start Time: {start}",
                    f"End Time: {end}",
                    f"Description: {description}",
                    f"Location: {location}",
                    "-" * 50,
                ])
                blocks.append(block)
            value = f"Successfully list events for {username}:\n" + "\n".join(blocks).rstrip()
    except Exception:
        value = f"Failed to list events for {username}."

print_json({"text": value})

