                in_event = True
                current = {}
                continue
            if line == "END:VEVENT":
                if in_event:
                    events.append(current)
                in_event = False
                current = {}
                continue
            if not in_event:
                continue
            if ":" not in line:
                continue
            left, val = line.split(":", 1)
            parts = left.split(";")
            prop = parts[0].upper()
            params = {}
            for p in parts[1:]:
                if "=" in p:
                    k, v = p.split("=", 1)
                    params[k.upper()] = v
            if prop in ("SUMMARY", "DESCRIPTION", "LOCATION", "DTSTART", "DTEND"):
                current[prop] = (params, val)

        if not events:
            value = f"No events found for {username}."
        else:
            blocks = []
            for ev in events:
                summary = unescape_text(ev["SUMMARY"][1]) if "SUMMARY" in ev else None
                description = unescape_text(ev["DESCRIPTION"][1]) if "DESCRIPTION" in ev else None
                location = unescape_text(ev["LOCATION"][1]) if "LOCATION" in ev else None

                if "DTSTART" in ev:
                    params, raw = ev["DTSTART"]
                    start = parse_dt(raw)
                else:
                    start = None
                if "DTEND" in ev:
                    params, raw = ev["DTEND"]
                    end = parse_dt(raw)
                else:
                    end = None

                block = "\n".join([
                    f"Summary: {summary}",
                    f"Start Time: {start}",
                    f"End Time: {end}",
                    f"Description: {description}",
                    f"Location: {location}",
                    "-" * 50,
                ])
                blocks.append(block)
            value = f"Successfully list events for {username}:\n" + "\n".join(blocks).rstrip()
    except Exception:
        value = f"Failed to list events for {username}."

print_json({"text": value})

